using System;using System.IO;using System.Collections;using System.Linq;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.EventSystems;using System.Collections.Generic;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class MainViewRepairTests {
  GameRuntime game;string dir;void Click(string id){var button=GameObject.Find(id)?.GetComponent<Button>();Assert.That(button,Is.Not.Null,id);Assert.That(button.interactable,Is.True,id);button.onClick.Invoke();}
  [UnitySetUp]public IEnumerator Setup(){
#if UNITY_EDITOR
PortraitGameView.Set();
#endif
yield return null;yield return null;Assert.That((float)Screen.height/Screen.width,Is.GreaterThan(1.9f),"Actual portrait display "+Screen.width+"x"+Screen.height);dir=Path.Combine(Path.GetTempPath(),"idle-mainview-"+Guid.NewGuid());Directory.CreateDirectory(dir);GameRuntime.SavePathOverride=Path.Combine(dir,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Directory.CreateDirectory("/tmp/idle-mainview-review");}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;if(dir!=null&&Directory.Exists(dir))Directory.Delete(dir,true);}
  [UnityTest]public IEnumerator FreshMiraActualActionsAndCompactLearningViewsSurviveReload(){
   foreach(string language in new[]{"de","en"}){game.Act(s=>{var n=s.Copy();n.Settings.language=language;return n;});yield return null;yield return null;Assert.That(GameObject.Find("MiraPortrait").GetComponent<Image>().sprite,Is.Not.Null);foreach(int width in new[]{320,390,430})yield return Capture(width,width==320?694:width==390?846:932,"/tmp/idle-mainview-review/mira-"+language+"-"+width+".png");}
   GameObject.Find("StoryNameInput").GetComponent<InputField>().text="AURA";Click("StoryChooseName");for(int i=0;i<20&&game.State.Story.open!=null;i++){yield return null;Click("StoryContinue");}yield return null;Click("TapLab");Click("hardware-calculator");Assert.That(game.State.Story.target,Is.EqualTo("training"));game.Show("training");yield return null;Assert.That(GameObject.Find("training-quality").GetComponent<LearningCard>(),Is.Not.Null);Click("training-quality");Assert.That(game.State.Journal.Has("training-start"),Is.True);
   foreach(string language in new[]{"de","en"}){game.Act(s=>{var n=s.Copy();n.Settings.language=language;return n;});foreach(string tab in new[]{"training","research"}){game.Show(tab);yield return null;yield return null;File.WriteAllLines("/tmp/idle-mainview-geometry-"+tab+".txt",UnityEngine.Object.FindObjectsByType<RectTransform>(FindObjectsSortMode.None).Where(r=>r.name=="AutomaticMira"||r.name=="SpeechBubble"||r.name=="Content"||r.name=="MiraPortrait").Select(r=>r.name+" parent="+r.parent.name+" rect="+r.rect+" world="+r.position+" scale="+r.localScale+" ignore="+r.GetComponent<LayoutElement>()?.ignoreLayout));Assert.That(game.Content.Find("StorageAccess"),Is.Null,"Administration belongs in the menu");foreach(int width in new[]{320,390,430})yield return Capture(width,width==320?694:width==390?846:932,"/tmp/idle-mainview-review/"+tab+"-"+language+"-"+width+".png");}}
   var loaded=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.Writable,Is.True,loaded.Message);Assert.That(loaded.State.Retention.aiName,Is.EqualTo("AURA"));Assert.That(loaded.State.Journal.Has("training-start"),Is.True);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Retention.aiName,Is.EqualTo("AURA"));Assert.That(game.State.QualityUsed,Is.True);Assert.That(Game.IntroQuality(game.State),Is.False);}
  [UnityTest]public IEnumerator SkipBeforeNamingAndResumeThroughMenuSurviveReload(){Click("StorySkipCurrent");yield return null;Assert.That(GameObject.Find("AutomaticMira"),Is.Null);Assert.That(game.State.Story.tutorial,Is.EqualTo("skipped"));Assert.That(Game.IntroQuality(game.State),Is.False);game.GetComponent<GameMenu>().Open();Click("Menu-story");yield return null;Click("StoryResume");Assert.That(game.State.Story.target,Is.EqualTo("name"));Assert.That(game.State.Story.open,Is.Null);Click("MenuReturn");yield return null;yield return null;Assert.That(GameObject.Find("AutomaticMira"),Is.Not.Null);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Story.tutorial,Is.EqualTo("active"));Assert.That(game.State.Story.target,Is.EqualTo("name"));Assert.That(game.State.Credits.CompareTo(ScientificNumber.From(Balance.StartCredits)),Is.Zero);}

  [UnityTest]public IEnumerator RepeatedViewsKeepOneDockAndClipContentAboveNavigation(){
   GameObject.Find("StoryNameInput").GetComponent<InputField>().text="AURA";Click("StoryChooseName");for(int i=0;i<30&&game.State.Story.open!=null;i++){yield return null;Click("StoryContinue");}yield return null;
   for(int pass=0;pass<10;pass++)foreach(string tab in new[]{"hardware","training","research"}){game.Show(tab);yield return null;yield return null;Canvas.ForceUpdateCanvases();Assert.That(UnityEngine.Object.FindObjectsByType<MiraCoach>(FindObjectsSortMode.None).Length,Is.EqualTo(1));Assert.That(UnityEngine.Object.FindObjectsByType<TutorialPointer>(FindObjectsSortMode.None).Length,Is.EqualTo(1));var bubble=GameObject.Find("SpeechBubble").GetComponent<RectTransform>();Assert.That(bubble.rect.width,Is.GreaterThan(200),"Speech must retain readable width");var viewport=game.Content.GetComponentInParent<ScrollRect>().viewport;var safe=game.GetComponentInParent<SafeArea>();if(safe==null)safe=game.Content.GetComponentInParent<SafeArea>();var nav=(RectTransform)safe.transform.Find("Tabs");var a=new Vector3[4];var b=new Vector3[4];viewport.GetWorldCorners(a);nav.GetWorldCorners(b);Assert.That(a[0].y,Is.GreaterThanOrEqualTo(b[1].y-1),"Viewport must end above navigation");Assert.That(game.Content.GetComponentsInChildren<LearningCard>().Length,Is.EqualTo(tab=="training"?3:tab=="research"?Balance.Research.Length:0));}
   Assert.That(game.SaveButton.gameObject.activeInHierarchy,Is.False);Assert.That(GameObject.Find("Menu").GetComponent<Button>(),Is.Not.Null);Assert.That(game.Status.gameObject.activeInHierarchy,Is.False);
  }
  [UnityTest]public IEnumerator HardwareModesKeepPurchaseGeometryAndThreeVisibleRows(){Click("StorySkipCurrent");yield return null;foreach(string language in new[]{"de","en"}){game.Act(s=>{var n=s.Copy();n.Settings.language=language;return n;});foreach(string mode in new[]{"1","10","max"}){Click("HardwareBuyMode-"+mode);yield return null;yield return null;Canvas.ForceUpdateCanvases();var rows=game.Content.GetComponentsInChildren<HardwarePresentation>();float width=-1;foreach(var row in rows){var buy=row.transform.Find("PurchaseCost/HardwarePurchase").GetComponent<RectTransform>();Assert.That(buy.rect.height,Is.GreaterThanOrEqualTo(44));if(width<0)width=buy.rect.width;Assert.That(buy.rect.width,Is.EqualTo(width).Within(.1));}var viewport=game.Content.GetComponentInParent<ScrollRect>().viewport;var corners=new Vector3[4];((RectTransform)rows[2].transform).GetWorldCorners(corners);Assert.That(viewport.InverseTransformPoint(corners[0]).y,Is.GreaterThanOrEqualTo(viewport.rect.yMin),"Three complete rows at actual iPhone aspect");foreach(int w in new[]{320,390,430})yield return Capture(w,w==320?694:w==390?846:932,"/tmp/idle-mainview-review/hardware-"+language+"-"+mode+"-"+w+".png");}}}
  [UnityTest]public IEnumerator ActiveTrainingKeepsUnlockedQueueActionReachableAndSaved(){
   game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Credits=ScientificNumber.From(1000000);n.Prestige.Cycle=n.Prestige.Total=n.Prestige.Free=n.Prestige.Entitlement=ScientificNumber.From(1000);return PrestigeRules.Buy(n,"T03");});game.Show("training");yield return null;var card=GameObject.Find("training-quality").GetComponent<LearningCard>();yield return Touch(card.StartAction.gameObject);Assert.That(game.State.Training,Is.Not.Null);Assert.That(card.StartAction.gameObject.activeInHierarchy,Is.True,"Unlocked queue is a meaningful action during active training");yield return Touch(card.StartAction.gameObject);yield return Touch(card.StartAction.gameObject);Assert.That(game.State.Prestige.trainingQueue.Length,Is.EqualTo(2));Assert.That(card.StartAction.gameObject.activeInHierarchy,Is.False,"A full queue must not offer a useless running button");var loaded=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.Writable,Is.True,loaded.Message);Assert.That(loaded.State.Prestige.trainingQueue.Length,Is.EqualTo(2));Assert.That(loaded.State.Training,Is.Not.Null);
  }
  IEnumerator Capture(int width,int height,string path){
#if UNITY_EDITOR
PortraitGameView.Set(width,height);yield return null;yield return null;
#endif
Assert.That(Screen.width,Is.EqualTo(width));WorkshopTests.Capture(width,height,path);}
  public static void CheckTextGeometry(){var coach=UnityEngine.Object.FindFirstObjectByType<MiraCoach>();if(coach!=null)Assert.That(coach.Speech.preferredHeight,Is.LessThanOrEqualTo(coach.Speech.rectTransform.rect.height+1),"Mira speech clipped");foreach(var card in UnityEngine.Object.FindObjectsByType<LearningCard>(FindObjectsSortMode.None))foreach(var text in new[]{card.Card.Title,card.Effect})Assert.That(text.preferredHeight,Is.LessThanOrEqualTo(text.rectTransform.rect.height+1),"Learning text clipped: "+text.text);}
  IEnumerator Touch(GameObject target){yield return null;Canvas.ForceUpdateCanvases();var pointer=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,target.transform.position)};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(pointer,hits);if(hits.Count==0){WorkshopTests.Capture(390,846,"/tmp/idle-native-route-failed-"+target.name+".png");File.WriteAllLines("/tmp/idle-native-route-failed-geometry.txt",UnityEngine.Object.FindObjectsByType<RectTransform>(FindObjectsSortMode.None).Where(r=>new[]{"TapLab","Content","Viewport","AutomaticMira","Laboratory","StoryShowTarget"}.Contains(r.name)).Select(r=>r.name+" parent="+r.parent.name+" rect="+r.rect+" world="+r.position+" active="+r.gameObject.activeInHierarchy));}Assert.That(hits.Count,Is.GreaterThan(0),target.name+" display="+Screen.width+"x"+Screen.height);Assert.That(ExecuteEvents.GetEventHandler<IPointerClickHandler>(hits[0].gameObject),Is.EqualTo(target),target.name);ExecuteEvents.Execute(target,pointer,ExecuteEvents.pointerClickHandler);yield return null;yield return null;}
  IEnumerator ContinueAll(){for(int i=0;i<30&&game.State.Story.open!=null;i++)yield return Touch(GameObject.Find("StoryContinue"));}
  [UnityTest]public IEnumerator GuidedHardwareToTrainingToResearchUsesReachableRaycastTargets(){GameObject.Find("StoryNameInput").GetComponent<InputField>().text="AURA";yield return Touch(GameObject.Find("StoryChooseName"));yield return ContinueAll();Assert.That(GameObject.Find("StoryDialogue").GetComponent<Text>().text,Does.Not.Contain("Halte gedrückt"));yield return Touch(game.TapButton.gameObject);yield return ContinueAll();yield return Touch(GameObject.Find("StoryShowTarget"));yield return Touch(GameObject.Find("hardware-calculator"));yield return ContinueAll();Assert.That(game.GetComponent<MobileShell>().Laboratory.gameObject.activeSelf,Is.True,"Same-tab guidance must keep the lab visible");yield return Touch(GameObject.Find("StoryShowTarget"));yield return Touch(GameObject.Find("training-quality").GetComponent<LearningCard>().StartAction.gameObject);yield return ContinueAll();yield return Touch(game.ResearchTab.gameObject);game.Content.GetComponentInParent<ScrollRect>().verticalNormalizedPosition=1;yield return null;yield return Touch(GameObject.Find("research-dataGeneration").GetComponent<LearningCard>().StartAction.gameObject);Assert.That(game.State.Journal.Has("training-start"),Is.True);Assert.That(game.State.Journal.Has("research-start"),Is.True);}

 }
